#!/usr/bin/env tsx
/**
 * Generate the Top-Level Help
 *
 * `sentry`, `sentry help`, and `sentry --help` list every top-level command,
 * but loading every command only to read their names and briefs is most of
 * what those runs cost. This script renders that help from the full route
 * tree at build time, so `src/app-for-args.ts` can run them with only the
 * `help` route loaded.
 *
 * The output is gitignored and regenerated by `generate:docs`, which runs as
 * part of `dev`, `build`, `bundle`, `typecheck`, and `test`.
 *
 * Usage:   tsx script/generate-root-help.ts
 * Output:  src/generated/root-help.json
 */

import { mkdirSync } from "node:fs";
import { access, writeFile } from "node:fs/promises";

// Bootstrap: skill-content stub (same pattern as generate-command-docs.ts).
// The route tree transitively imports skill-content.ts, which may not exist
// yet on a fresh checkout. Must run before the dynamic import below.
const SKILL_CONTENT_PATH = "src/generated/skill-content.ts";
const SKILL_CONTENT_STUB =
  "export const SKILL_FILES: [string, string][] = [];\n";
const skillContentExists = await access(SKILL_CONTENT_PATH).then(
  () => true,
  () => false,
);
if (!skillContentExists) {
  mkdirSync("src/generated", { recursive: true });
  await writeFile(SKILL_CONTENT_PATH, SKILL_CONTENT_STUB);
}

const { app, routes } = await import("../src/app.js");
const { buildRootHelp } = await import("./lib/root-help.js");

const OUTPUT_PATH = "src/generated/root-help.json";

const rootHelp = await buildRootHelp(app, routes);
mkdirSync("src/generated", { recursive: true });
await writeFile(OUTPUT_PATH, `${JSON.stringify(rootHelp, null, 2)}\n`);
process.stdout.write(
  `Wrote ${OUTPUT_PATH} (${rootHelp.commands.length} commands)\n`,
);
